package com.jnapanam.sportszone.release1.service;
import com.jnapanam.sportszone.notification.model.NotificationChannel;import com.jnapanam.sportszone.notification.service.NotificationService;import java.time.*;import java.util.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ReminderJob{private final org.springframework.jdbc.core.JdbcTemplate j;private final NotificationService n;public ReminderJob(org.springframework.jdbc.core.JdbcTemplate j,NotificationService n){this.j=j;this.n=n;}
 @Scheduled(cron="0 0 8 * * *",zone="Asia/Kolkata")@Transactional public void daily(){LocalDate tomorrow=LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(1);for(Map<String,Object>x:j.queryForList("select b.id,b.user_id,f.name facility_name,s.start_time from bookings b join booking_slots s on s.id=b.slot_id join facilities f on f.id=s.facility_id where s.slot_date=? and b.status='CONFIRMED'",tomorrow))send((UUID)x.get("user_id"),"BOOKING_REMINDER","BOOKING",(UUID)x.get("id"),"Booking reminder","Your booking at "+x.get("facility_name")+" is tomorrow at "+x.get("start_time"));LocalDate expiry=LocalDate.now().plusDays(7);for(Map<String,Object>x:j.queryForList("select cm.id,cm.user_id,mp.name from customer_memberships cm join membership_plans mp on mp.id=cm.plan_id where cm.end_date=? and cm.status='ACTIVE'",expiry))send((UUID)x.get("user_id"),"MEMBERSHIP_EXPIRY","MEMBERSHIP",(UUID)x.get("id"),"Membership expires soon",x.get("name")+" expires in 7 days. Renew to continue benefits.");for(Map<String,Object>x:j.queryForList("select te.id,te.user_id,tb.name from training_enrollments te join training_batches tb on tb.id=te.batch_id where tb.start_date=? and te.status in ('ENROLLED','ACTIVE')",tomorrow))send((UUID)x.get("user_id"),"TRAINING_REMINDER","TRAINING",(UUID)x.get("id"),"Training reminder",x.get("name")+" starts tomorrow.");for(Map<String,Object>x:j.queryForList("select tt.id,tt.captain_user_id,t.name from tournament_teams tt join tournaments t on t.id=tt.tournament_id where t.start_date=? and tt.status<>'CANCELLED'",tomorrow))send((UUID)x.get("captain_user_id"),"TOURNAMENT_REMINDER","TOURNAMENT",(UUID)x.get("id"),"Tournament reminder",x.get("name")+" starts tomorrow.");}
 private void send(UUID user,String category,String type,UUID ref,String subject,String msg){Integer exists=j.queryForObject("select count(*) from reminder_schedule where user_id=? and category=? and reference_id=? and status in ('PENDING','SENT')",Integer.class,user,category,ref);if(exists!=null&&exists>0)return;UUID id=UUID.randomUUID();j.update("insert into reminder_schedule(id,user_id,category,reference_type,reference_id,scheduled_at,status) values(?,?,?,?,?,now(),'PENDING')",id,user,category,type,ref);try{n.notify(user,category,subject,msg);n.notifyChannel(user,NotificationChannel.EMAIL,category,subject,msg);j.update("update reminder_schedule set status='SENT' where id=?",id);}catch(Exception e){j.update("update reminder_schedule set status='FAILED' where id=?",id);}}}
